namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Name = "Breakfast", Description = "Start your day right with hearty morning meals", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Quick and satisfying midday recipes", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Delicious evening meals for the whole family", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats to end any meal", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Light bites for any time of day", Icon = "🍿" },
            new() { Name = "Beverages", Description = "Refreshing drinks and smoothies", Icon = "🥤" }
        };

        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Pancakes", Category = "Breakfast", Ingredients = "2 cups flour
2 eggs
1 cup milk
2 tbsp sugar
1 tsp baking powder
Butter for cooking", Steps = "1. Mix dry ingredients in a bowl
2. Whisk eggs and milk together
3. Combine wet and dry ingredients
4. Heat butter in a pan
5. Pour batter and cook until bubbles form
6. Flip and cook other side until golden", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Caesar Salad", Category = "Lunch", Ingredients = "1 head romaine lettuce
1/2 cup croutons
1/4 cup parmesan cheese
Caesar dressing
Grilled chicken (optional)", Steps = "1. Wash and chop romaine lettuce
2. Toss with Caesar dressing
3. Top with croutons and parmesan
4. Add grilled chicken if desired
5. Serve immediately", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner", Ingredients = "400g spaghetti
500g ground beef
1 onion, diced
2 cloves garlic
400g crushed tomatoes
2 tbsp tomato paste
Italian herbs
Salt and pepper", Steps = "1. Cook spaghetti according to package
2. Brown ground beef in a pan
3. Add onion and garlic, cook until soft
4. Add tomatoes, paste, and herbs
5. Simmer for 20 minutes
6. Serve sauce over spaghetti", AverageRating = 4.8, RatingCount = 24 },
            new() { Id = 4, Title = "Chocolate Brownies", Category = "Desserts", Ingredients = "200g dark chocolate
150g butter
3 eggs
1 cup sugar
3/4 cup flour
1 tsp vanilla extract
Pinch of salt", Steps = "1. Preheat oven to 180°C (350°F)
2. Melt chocolate and butter together
3. Whisk eggs and sugar until fluffy
4. Fold in chocolate mixture
5. Add flour, vanilla, and salt
6. Pour into lined baking pan
7. Bake for 25 minutes", AverageRating = 4.9, RatingCount = 31 },
            new() { Id = 5, Title = "Trail Mix Energy Bites", Category = "Snacks", Ingredients = "1 cup oats
1/2 cup peanut butter
1/3 cup honey
1/2 cup chocolate chips
1/4 cup dried cranberries
2 tbsp chia seeds", Steps = "1. Mix all ingredients in a bowl
2. Refrigerate for 30 minutes
3. Roll into small balls
4. Store in refrigerator
5. Enjoy as needed!", AverageRating = 4.3, RatingCount = 15 },
            new() { Id = 6, Title = "Berry Smoothie", Category = "Beverages", Ingredients = "1 cup mixed berries
1 banana
1 cup yogurt
1/2 cup orange juice
1 tbsp honey
Ice cubes", Steps = "1. Add all ingredients to blender
2. Blend until smooth
3. Add more juice if too thick
4. Pour into glass and serve", AverageRating = 4.1, RatingCount = 9 }
        };
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is null) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
    }
}

