@page "/category/{CategoryName}"
@using RecipeHub.Services

@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category yet. <a href="/submit">Be the first to add one!</a></div>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<RecipeHub.Models.Recipe> Recipes { get; set; } = new();

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services

@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@Recipe.Category.ToLower()">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1>@Recipe.Title</h1>
        <p class="text-muted">Category: @Recipe.Category | ⭐ @Recipe.AverageRating.ToString("F1") (@Recipe.RatingCount ratings)</p>

        <div class="row mt-4">
            <div class="col-md-4">
                <div class="card">
                    <div class="card-header"><h5 class="mb-0">🧾 Ingredients</h5></div>
                    <div class="card-body">
                        <ul class="list-unstyled">
                            @foreach (var ingredient in Recipe.Ingredients.Split('\n'))
                            {
                                <li class="mb-1">• @ingredient</li>
                            }
                        </ul>
                    </div>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card">
                    <div class="card-header"><h5 class="mb-0">👨‍🍳 Steps</h5></div>
                    <div class="card-body">
                        @foreach (var step in Recipe.Steps.Split('\n'))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>

        <div class="mt-4">
            <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeHub.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services

@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit Your Recipe</h1>

    @if (Submitted)
    {
        <div class="alert alert-success">
            <h4>🎉 Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@NewRecipe.Title</strong>" has been added to the @NewRecipe.Category category.</p>
            <a href="/category/@NewRecipe.Category.ToLower()" class="btn btn-primary">View Category</a>
            <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
        </div>
    }
    else
    {
        <EditForm Model="NewRecipe" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="NewRecipe.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="NewRecipe.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Name</option>
                    }
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="NewRecipe.Ingredients" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps (one per line)</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="NewRecipe.Steps" placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
            </div>

            <button type="submit" class="btn btn-success btn-lg" disabled="@(!IsFormValid)">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private Recipe NewRecipe { get; set; } = new();
    private bool Submitted { get; set; }

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(NewRecipe.Title) &&
        !string.IsNullOrWhiteSpace(NewRecipe.Category) &&
        !string.IsNullOrWhiteSpace(NewRecipe.Ingredients) &&
        !string.IsNullOrWhiteSpace(NewRecipe.Steps);

    private void HandleSubmit()
    {
        if (!IsFormValid) return;
        RecipeService.AddRecipe(NewRecipe);
        Submitted = true;
    }

    private void Reset()
    {
        NewRecipe = new Recipe();
        Submitted = false;
    }
}

@using RecipeHub.Services

@inject RecipeService RecipeService

<div class="card">
    <div class="card-body">
        <h5 class="card-title">Rate this recipe</h5>
        <div class="d-flex align-items-center gap-2">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <button class="btn btn-link fs-3 p-0 text-decoration-none"
                        @onclick="() => SubmitRating(star)"
                        disabled="@HasRated"
                        title="Rate @star stars">
                    @(star <= (HoverRating > 0 ? HoverRating : SelectedRating) ? "⭐" : "☆")
                </button>
            }
            @if (HasRated)
            {
                <span class="text-success ms-2">✓ Thanks for rating!</span>
            }
        </div>
    </div>
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int SelectedRating { get; set; }
    private int HoverRating { get; set; }
    private bool HasRated { get; set; }

    private void SubmitRating(int stars)
    {
        if (HasRated) return;
        SelectedRating = stars;
        HasRated = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

